function updateLastUpdated() {
  const d = getData();
  const ts = manualRefreshAt || d.generated_at;
  if (ts) {
    const dt = new Date(ts);
    const now = new Date();
    const diff = Math.round((now - dt) / 60000);
    const label = diff < 1 ? 'just now' : diff < 60 ? `${diff}m ago` : `${Math.round(diff/60)}h ago`;
    document.getElementById('last-updated').textContent = `Updated ${label}`;
  }
}

